class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        slow = fast = nums[0]
        while True:                       # phase 1: meet inside the cycle
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        slow = nums[0]                    # phase 2: walk to the cycle entrance
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow
